const storage = 'cursor-knowledge-workspace-v1'
function loadState(userId:string) {
  try {
    const value = JSON.parse(localStorage.getItem(`${storage}:${userId}`) || 'null');
    if (Array.isArray(value?.resources) && Array.isArray(value?.threads)) {
      if (value.resources.some((r: Resource) => starterResourceIds.has(r?.id)) || value.threads.some((t: Thread) => t?.id === 'voice-project')) {
        try { if (!localStorage.getItem(`${storage}:starter-archive`)) localStorage.setItem(`${storage}:starter-archive`, JSON.stringify(value)); } catch { /* Keep the active library usable if the archive is too large. */ }
      }
      return {
      resources: value.resources.filter((r: Resource) => typeof r?.id === 'string' && Array.isArray(r.sections) && !starterResourceIds.has(r.id)),
      threads: value.threads.filter((t: Thread) => typeof t?.id === 'string' && Array.isArray(t.messages) && t.id !== 'voice-project'),
    } as {resources: Resource[]; threads: Thread[]};
    }
  } catch { /* Start empty if browser storage is unavailable. */ }
  return { resources: [] as Resource[], threads: [] as Thread[] };
}
const pill = 'inline-flex items-center gap-1 rounded-[5px] border border-[var(--ink)]/7 bg-[var(--ink)]/3 px-[7px] py-[2px] text-[11px] leading-[16px] text-[var(--secondary)]'
const quietButton = 'flex items-center justify-center gap-[6px] rounded-[6px] px-[9px] py-[6px] text-[12px] text-[var(--secondary)] transition-colors hover:bg-[var(--ink)]/5 hover:text-[var(--primary)]'
