function Mark({ name, size = 16 }: {name: string; size?: number}) {
  if (name === 'library' || name === 'image' || name === 'star' || name === 'note') return <svg width={size} height={size} viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{name === 'library' ? <><path d="M3 3h4v14H3zm6 0h4v14H9zm6 1 2-.5 3 13-2 .5z"/></> : name === 'image' ? <><rect x="2.5" y="3" width="15" height="14" rx="2"/><circle cx="7" cy="7.5" r="1.3"/><path d="m3 14 4-4 3 3 3-5 4 6"/></> : name === 'star' ? <path d="m10 2 2.4 5 5.6.8-4 4 .9 5.5-4.9-2.6-4.9 2.6.9-5.5-4-4 5.6-.8z"/> : <><path d="M5 2h7l4 4v12H5zM12 2v4h4M8 10h5m-5 3h5"/></>}</svg>
  return <Icon name={name as IconName} size={size}/>
}
function Tag({ children }: {children: string}) { return <span className={pill}>{children}</span> }
function getDraft(r: Resource, format: DraftFormat) {
  if (format === 'Tweet') return `${r.title}: ${r.summary}\n\n${r.url || 'From my knowledge library'}\n\n#${(r.tags[0] || 'Knowledge').replace(/[^a-zA-Z0-9]/g, '')}`
  if (format === 'Tweet JSON') return JSON.stringify({ type: 'tweet_draft', text: `${r.title}: ${r.summary}`, links: r.url ? [r.url] : [], source_ids: [r.id], tags: r.tags, status: 'draft' }, null, 2)
  if (format === 'Image brief') return `Editorial cover for “${r.title}”\n\nIdea: ${r.subtitle}\nVisual direction: use the actual source screenshot, image, or original video thumbnail. Preserve creator attribution.\nFormat: landscape, with room for a square crop.\nAlt text: original source reference accompanying ${r.title}.\n\nReference: ${r.url || 'Workspace note'}\nStatus: brief only; no image generated.`
  return `# ${r.title}: ${r.subtitle}\n\nOpening\n${r.summary}\n\n${r.sections.map((s, i) => `${i+1}. ${s.title}\n   ${s.paragraphs[0]}`).join('\n\n')}\n\nEditorial angle\n${r.editorial}\n\nSource\n${r.url || 'Original workspace note'}`
}

